begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values('11111111-1111-4111-8111-111111111111','owner@example.invalid',now()),('22222222-2222-4222-8222-222222222222','other@example.invalid',now());
create temporary table fixture(key text primary key,id uuid);
grant all on fixture to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
insert into fixture values('brand',public.create_owner_workspace('Owner','Test Brand','UTC','','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true));
select throws_ok($$select public.request_research((select id from fixture where key='brand'),'audit','',gen_random_uuid())$$,'22023',null,'Audit requires actual saved website');
select lives_ok($$select public.update_brand_settings((select id from fixture where key='brand'),'Test Brand','https://example.invalid','Asia/Kolkata')$$,'Owner can update website and timezone');
select throws_ok($$select public.update_brand_settings((select id from fixture where key='brand'),'Test Brand','','Invalid/Zone')$$,'22023',null,'Invalid timezone rejected');
select throws_ok($$select public.create_observation_cohort((select id from fixture where key='brand'),'Questions',array['Which product?'],array['test brand'],'India','English','test-model',1,true)$$,'22023',null,'Duplicate brand comparison rejected');
insert into fixture values('cohort',public.create_observation_cohort((select id from fixture where key='brand'),'Questions',array['Which product?'],array['Competitor'],'India','English','test-model',2,true));
select throws_ok($$select public.request_research((select id from fixture where key='brand'),'observation',(select id::text from fixture where key='cohort'),gen_random_uuid())$$,'54000',null,'Observation collection is disabled by default quota');
select public.set_observation_allowance((select id from fixture where key='brand'),2);
insert into fixture values('run',public.request_research((select id from fixture where key='brand'),'observation',(select id::text from fixture where key='cohort'),'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'));
select is(public.request_research((select id from fixture where key='brand'),'observation',(select id::text from fixture where key='cohort'),'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),(select id from fixture where key='run'),'Idempotency does not reserve more requests');
select is((select expected_samples from public.research_runs),2,'Run reserves entire planned denominator');
select throws_ok($$select private.schedule_observations()$$,'42501',null,'Client cannot invoke scheduled impersonation');
select throws_ok($$insert into public.observation_samples(brand_id,run_id,ordinal,question,state,answer) values((select id from fixture where key='brand'),(select id from fixture where key='run'),0,'Question','complete','Invented')$$,'42501',null,'Client cannot fabricate observations');
reset role;
select is((select count(*)::int from private.research_outbox),1,'Research and outbox committed together');
select ok(private.research_authorized((select id from fixture where key='run')),'Current owner authorizes worker');
insert into public.observation_samples(brand_id,run_id,ordinal,question,state,answer,mentions) values((select id from fixture where key='brand'),(select id from fixture where key='run'),0,'Which product?','complete','Test Brand','{"Test Brand":true}');
select throws_ok($$update public.observation_samples set answer='Changed'$$,'42501',null,'Observation evidence is immutable');
update public.brand_memberships set active=false where user_id='11111111-1111-4111-8111-111111111111';
select ok(not private.research_authorized((select id from fixture where key='run')),'Revoked actor blocks in-flight evidence commit');
update public.brand_memberships set active=true where user_id='11111111-1111-4111-8111-111111111111';
set local role authenticated;
select public.cancel_research((select id from fixture where key='brand'),(select id from fixture where key='run'));
select is((select state from public.research_runs),'cancelled','Owner cancellation persists');
select throws_ok($$select public.request_research((select id from fixture where key='brand'),'observation',(select id::text from fixture where key='cohort'),gen_random_uuid())$$,'54000',null,'Cancellation does not refund potentially billed allowance');
select throws_ok($$select public.acknowledge_baseline((select id from fixture where key='brand'),'Scope','Gaps','Owner',gen_random_uuid(),false)$$,'22023',null,'Baseline requires explicit acknowledgement');
insert into fixture values('review',public.acknowledge_baseline((select id from fixture where key='brand'),'Questions and website','Analytics unavailable','Owner reviews weekly','cccccccc-cccc-4ccc-8ccc-cccccccccccc',true));
select is(public.acknowledge_baseline((select id from fixture where key='brand'),'Changed','Changed','Changed','cccccccc-cccc-4ccc-8ccc-cccccccccccc',true),(select id from fixture where key='review'),'Baseline retry returns immutable original');
select is((select snapshot->>'completed_observations' from public.baseline_reviews),'1','Snapshot captures actual completed samples');
select public.update_brand_settings((select id from fixture where key='brand'),'Renamed','https://example.invalid','UTC');
select is((select snapshot->'brand'->>'name' from public.baseline_reviews),'Test Brand','Settings changes do not rewrite acknowledged context');
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
select is((select count(*)::int from public.research_runs),0,'Other tenant cannot read research');
select is((select count(*)::int from public.observation_samples),0,'Other tenant cannot read raw answers');
select is((select count(*)::int from public.observation_cohorts),0,'Other tenant cannot read cohorts');
select is((select count(*)::int from public.baseline_reviews),0,'Other tenant cannot read reviews');
select throws_ok($$select public.update_brand_settings((select id from fixture where key='brand'),'Hijacked','','UTC')$$,'42501',null,'Other tenant cannot change settings');
select throws_ok($$select public.acknowledge_baseline((select id from fixture where key='brand'),'Scope','Gaps','Owner',gen_random_uuid(),true)$$,'42501',null,'Other tenant cannot acknowledge baseline');
select throws_ok($$select public.cancel_research((select id from fixture where key='brand'),(select id from fixture where key='run'))$$,'42501',null,'Other tenant cannot cancel run');
select throws_ok($$select public.set_observation_allowance((select id from fixture where key='brand'),1000)$$,'42501',null,'Other tenant cannot raise observation allowance');
reset role;
select * from finish();
rollback;
